H^\bullet_\mathrm{vir}(X\operatorname{rel}\partial;A)\ar{r}{\eqref{sesofF}}\ar[equal]{d}{\text{Thm \ref{Fsheaffundamentaliso}}}&H^\bullet_\mathrm{vir}(X;A)\ar{r}{\eqref{sesofF}}\ar[equal]{d}{\text{Thm \ref{Fsheaffundamentaliso}}}&H^\bullet_\mathrm{vir}(\partial X;A)\ar{r}{\eqref{sesofF}}\ar[equal]{d}{\text{Thm \ref{Fsheaffundamentaliso}}}&H^{\bullet+1}_\mathrm{vir}(X\operatorname{rel}\partial;A)\ar[equal]{d}{\text{Thm \ref{Fsheaffundamentaliso}}}\\
\check H^\bullet(X;\mathfrak o_{X\operatorname{rel}\partial})\ar{r}{\eqref{sesofO}}&\check H^\bullet(X;\mathfrak o_X)\ar{r}{\eqref{sesofO}}&\check H^\bullet(\partial X;\mathfrak o_{\partial X})\ar{r}{\eqref{sesofO}}&\check H^{\bullet+1}(X;\mathfrak o_{X\operatorname{rel}\partial})
