\end{equation}
for $e(X)\in H^2_{S^1}(X)$.  The same reasoning applies for pairs of spaces, so the same exact sequence exists for relative homology as well.

\begin{equation}\label{gysinserregeneral}
\cdots\xrightarrow{\cap e}H_{\bullet-1}(B)\xrightarrow{\pi^!}H_\bullet(E)\xrightarrow{\pi_\ast}H_\bullet(B)\xrightarrow{\cap e}H_{\bullet-2}(B)\xrightarrow{\pi^!}\cdots
\end{equation}

\begin{equation}\label{gysinserre}
