\label{complexconventions}
By a \emph{complex} $C^\bullet$ we mean a $\mathbb Z$-graded object $\bigoplus_{i\in\mathbb Z}C^i$ (in some abelian category) along with a degree $1$ endomorphism $d$ with $d^2=0$.  The \emph{homology} of a complex $C^\bullet$ is denoted $H^\bullet C^\bullet$ (defined by $H^iC^\bullet:=\ker(C^i\xrightarrow dC^{i+1})/\operatorname{im}(C^{i-1}\xrightarrow dC^i)$).  A complex is called \emph{acyclic} iff its homology vanishes.  A map of complexes $f:A^\bullet\to B^\bullet$ is a called a \emph{quasi-isomorphism} iff it induces an isomorphism on homology.  We will often use the fact that a map of complexes is a quasi-isomorphism iff its mapping cone is acyclic.

The \emph{shift} of a complex $C^\bullet[n]$ is defined by $(C^\bullet[n])^i:=C^{i+n}$.  We use the \emph{truncation functors} defined by:
\begin{equation*}
(\tau_{\geq i}C^\bullet)^j:=\begin{cases}C^j&j>i\cr\operatorname{coker}(C^{i-1}\xrightarrow dC^i)&j=i\cr 0&j<i\end{cases}\qquad
(\tau_{\leq i}C^\bullet)^j:=\begin{cases}0&j>i\cr\ker(C^i\xrightarrow dC^{i+1})&j=i\cr C^j&j<i\end{cases}
\end{equation*}
Given a sequence of maps of complexes $A_0^\bullet\to\cdots\to A_n^\bullet$ such that adjacent maps compose to zero, we denote by $[A_0^\bullet\to\cdots\to A_n^{\bullet-n}]$ the associated total complex of this double complex.  For example, $f:A^\bullet\to B^\bullet$ denotes a map, and $[A^\bullet\xrightarrow fB^{\bullet-1}]$ denotes its mapping cone.

\begin{equation*}
(\tau_{\geq i}C^\bullet)^j:=\begin{cases}C^j&j>i\cr\operatorname{coker}(C^{i-1}\xrightarrow dC^i)&j=i\cr 0&j<i\end{cases}\qquad
(\tau_{\leq i}C^\bullet)^j:=\begin{cases}0&j>i\cr\ker(C^i\xrightarrow dC^{i+1})&j=i\cr C^j&j<i\end{cases}
\end{equation*}

A \emph{sheaf} is a presheaf $\mathcal F$ satisfying the following condition:
\begin{equation*}
\tag{Sh}\label{opensheafproperty}0\to\mathcal F\Bigl(\bigcup_{\alpha\in A}U_\alpha\Bigr)\to\prod_{\alpha\in A}\mathcal F(U_\alpha)\to\prod_{\alpha,\beta\in A}\mathcal F(U_\alpha\cap U_\beta)\quad\text{ is exact }\forall\text{ }\{U_\alpha\subseteq X\}_{\alpha\in A}
\end{equation*}
The category of sheaves on a space $X$ is denoted $\operatorname{Shv} X$ (a full subcategory of $\operatorname{Prshv} X$, meaning a morphism between sheaves is the same as a morphism of the corresponding presheaves).

\begin{equation*}
\tag{Sh}\label{opensheafproperty}0\to\mathcal F\Bigl(\bigcup_{\alpha\in A}U_\alpha\Bigr)\to\prod_{\alpha\in A}\mathcal F(U_\alpha)\to\prod_{\alpha,\beta\in A}\mathcal F(U_\alpha\cap U_\beta)\quad\text{ is exact }\forall\text{ }\{U_\alpha\subseteq X\}_{\alpha\in A}
\end{equation*}

A \emph{$\mathcal K$-sheaf} is a $\mathcal K$-presheaf $\mathcal F$ satisfying the following three conditions:\footnote{A similar set of axioms appears in Lurie \cite[Definition 7.3.4.1]{luriehtt}.}
\begin{align*}
\tag{Sh$_\mathcal K$1}\label{sheafvanishing}\mathcal F(\varnothing)&=0\\
\tag{Sh$_\mathcal K$2}\label{sheafproperty}0\to\mathcal F(K_1\cup K_2)\to\mathcal F(K_1)\oplus\mathcal F(K_2)\to\mathcal F(K_1\cap K_2)&\text{ is exact }\forall\text{ }K_1,K_2\subseteq X\\
\tag{Sh$_\mathcal K$3}\label{sheafcontinuity}\varinjlim_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\mathcal F(\overline U)\to\mathcal F(K)&\text{ is an isomorphism }\forall\text{ }K\subseteq X
\end{align*}
The category of $\mathcal K$-sheaves on a space $X$ is denoted $\operatorname{Shv}_\mathcal K X$ (a full subcategory of $\operatorname{Prshv}_\mathcal K X$).

\begin{align*}
\tag{Sh$_\mathcal K$1}\label{sheafvanishing}\mathcal F(\varnothing)&=0\\
\tag{Sh$_\mathcal K$2}\label{sheafproperty}0\to\mathcal F(K_1\cup K_2)\to\mathcal F(K_1)\oplus\mathcal F(K_2)\to\mathcal F(K_1\cap K_2)&\text{ is exact }\forall\text{ }K_1,K_2\subseteq X\\
\tag{Sh$_\mathcal K$3}\label{sheafcontinuity}\varinjlim_{\begin{smallmatrix}K\subseteq U\cr U\textrm{ open}\end{smallmatrix}}\mathcal F(\overline U)\to\mathcal F(K)&\text{ is an isomorphism }\forall\text{ }K\subseteq X
\end{align*}

